/**
 * Hand-written catalogue for the search bench. About 300 South African
 * retail listings. Nothing here was scraped.
 *
 * A few descriptions deliberately share one query word ("warm", "stationery",
 * "pounding", "cold") so Reciprocal Rank Fusion has a weak lexical hit to
 * promote, while distractor titles use that same word in a stronger position.
 * The rules are checked in catalog.test.ts. SKUs and ISBNs are not embedded.
 */

export type SeedProduct = {
  sku: string;
  title: string;
  brand: string;
  category: string;
  priceCents: number;
  description: string;
  isbn?: string;
};

function item(
  sku: string,
  title: string,
  brand: string,
  category: string,
  priceCents: number,
  description: string,
  isbn?: string,
): SeedProduct {
  return { sku, title, brand, category, priceCents, description, isbn };
}

